import{_ as t,c as a,o as e,ag as o}from"./chunks/framework.ymCRTBvy.js";const p=JSON.parse('{"title":"📘 《iOS 18 UIKit纯代码组件化与重构实战》","description":"","frontmatter":{},"headers":[],"relativePath":"uikit/uikit_refactor/index.md","filePath":"uikit/uikit_refactor/index.md"}'),r={name:"uikit/uikit_refactor/index.md"};function l(n,i,d,s,u,_){return e(),a("div",null,i[0]||(i[0]=[o('<h1 id="📘-《ios-18-uikit纯代码组件化与重构实战》" tabindex="-1">📘 《iOS 18 UIKit纯代码组件化与重构实战》 <a class="header-anchor" href="#📘-《ios-18-uikit纯代码组件化与重构实战》" aria-label="Permalink to &quot;📘 《iOS 18 UIKit纯代码组件化与重构实战》&quot;">​</a></h1><h2 id="📖-内容简介" tabindex="-1">📖 内容简介： <a class="header-anchor" href="#📖-内容简介" aria-label="Permalink to &quot;📖 内容简介：&quot;">​</a></h2><p>本书是面向中高级iOS开发者的深度实战指南，聚焦于UIKit框架下纯代码组件化开发与系统重构的进阶实践。全书从现代化项目配置与无Storyboard启动流程入手，系统讲解Auto Layout约束体系、声明式布局技术，并深入探讨高内聚、低耦合的组件化架构设计。</p><p>不同于传统UI开发教程，本书特别关注大规模应用中的代码质量与架构演进，提供从代码坏味识别到系统重构的完整方法论。涵盖从基础视图封装到复杂设计模式应用，从数据驱动UI到跨框架互操作，帮助开发者构建可维护、可扩展的现代化iOS应用。</p><p>通过15个精心设计的章节，本书系统性地讲解了如何通过组件化思维重构臃肿代码库，每章都配有可直接应用于企业级项目的实战案例和架构最佳实践。</p><h2 id="✅-你将学到" tabindex="-1">✅ 你将学到： <a class="header-anchor" href="#✅-你将学到" aria-label="Permalink to &quot;✅ 你将学到：&quot;">​</a></h2><ul><li>掌握纯代码构建复杂UI界面的能力</li><li>精通Auto Layout和声明式布局技术</li><li>能够设计和实现高内聚、低耦合的UI组件</li><li>熟练运用MVP、MVVM等设计模式进行架构</li><li>掌握事件回调、数据绑定和状态管理机制</li><li>能够重构臃肿的视图控制器和重复代码</li><li>学会使用依赖注入和Coordinator模式解耦</li><li>能够封装自定义视图、控件及数据源</li><li>掌握UIKit与SwiftUI的互操作性</li><li>具备UI性能分析和优化能力</li></ul><p>本书适合已具备UIKit开发经验，希望提升代码质量、掌握组件化架构并应对复杂业务场景的中高级开发者。通过学习本书，您将能够将庞杂的UI代码重构为清晰可维护的组件系统，构建出架构优雅、性能卓越且易于团队协作的iOS应用。</p>',8)]))}const h=t(r,[["render",l]]);export{p as __pageData,h as default};
